// HAL animated favicon — include on your page: <script src="hal-favicon.js"></script>
(function(){
var frames=["data:image/png;base64,","data:image/png;base64,","data:image/png;base64,"];
// sequence: hold bright, quick dim-blink, back
var seq=[[0,2600],[1,90],[2,160],[1,90]];
var link=document.querySelector('link[rel~="icon"]');
if(!link){link=document.createElement('link');link.rel='icon';document.head.appendChild(link);}
link.type='image/png';
var i=0;
function step(){link.href=frames[seq[i][0]];var d=seq[i][1];i=(i+1)%seq.length;setTimeout(step,d);}
step();
})();